dition\": []}, {\"key\": \"ac.sys{n}.line{m}.voltage_v\", \"type\": \"pemon_read\", \"unit\": \"V\", \"label\": \"AC {n} Line {m} Voltage\", \"scale\": 1, \"enable\": true, \"source\": \"http\", \"datatype\": \"float\", \"protocol\": \"pemon\", \"triggers\": [], \"pull_rate\": 30, \"description\": \"View1 VAC. Line count follows ACs.\", \"store_policy\": \"always\", \"normal_condition\": []}, {\"key\": \"ac.sys{n}.line{m}.current_a\", \"type\": \"pemon_read\", \"unit\": \"A\", \"label\": \"AC {n} Line {m} Current\", \"scale\": 1, \"enable\": true, \"source\": \"http\", \"datatype\": \"float\", \"protocol\": \"pemon\", \"triggers\": [], \"pull_rate\": 30, \"description\": \"View1 IAC.\", \"store_policy\": \"always\", \"normal_condition\": []}, {\"key\": \"io.sys{n}.temp{k}_c\", \"type\": \"pemon_read\", \"unit\": \"\u00b0C\", \"label\": \"IO {n} Temperature {k}\", \"scale\": 1, \"enable\": true, \"source\": \"http\", \"datatype\": \"float\", \"protocol\": \"pemon\", \"triggers\": [], \"pull_rate\": 30, \"description\": \"Enabled temperature sensors only.\", \"store_policy\": \"always\", \"normal_condition\": []}, {\"key\": \"io.sys{n}.hum{k}_pct\", \"type\": \"pemon_read\", \"unit\": \"%\", \"label\": \"IO {n} Humidity {k}\", \"scale\": 1, \"enable\": true, \"source\": \"http\", \"datatype\": \"float\", \"protocol\": \"pemon\", \"triggers\": [], \"pull_rate\": 30, \"description\": \"Enabled humidity sensors only.\", \"store_policy\": \"always\", \"normal_condition\": []}, {\"key\": \"io.sys{n}.in{k}\", \"type\": \"pemon_read\", \"unit\": \"\", \"label\": \"IO {n} Input {k}\", \"scale\": 1, \"enable\": true, \"source\": \"http\", \"datatype\": \"int\", \"protocol\": \"pemon\", \"triggers\": [], \"pull_rate\": 30, \"description\": \"1 when that input is in fault.\", \"store_policy\": \"on_change\", \"normal_condition\": []}, {\"key\": \"dc.limit.high_float_v\", \"oid\": \"1.3.6.1.4.1.12807.3.1.1.1.1.0\", \"type\": \"pemon_read\", \"unit\": \"V\", \"label\": \"DC High F